function loadSamplePaperNav(){const t=document.querySelector(".sample-paper-nav");if(!t)return;const a=[{name:"Set 1",file:"set1/index.html"},{name:"Set 2",file:"set2/index.html"},{name:"Set 3",file:"set3/index.html"},{name:"Set 4",file:"set4/index.html"},{name:"Set 5",file:"set5/index.html"},{name:"Set 6",file:"set6/index.html"},{name:"Set 7",file:"set7/index.html"}],i=window.location.pathname,s=i.includes("/set");let n=`
        <div class="sp-nav-inner">
            <span class="sp-nav-label">Quick Switch:</span>
            <div class="sp-nav-list">
    `;a.forEach(e=>{const l=e.file.split("/")[0],c=i.includes("/"+l+"/")?"active":"",d=s?"../"+e.file:e.file;n+=`<a href="${d}" class="sp-nav-link ${c}">${e.name}</a>`}),n+="</div></div>",t.innerHTML=n}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",loadSamplePaperNav):loadSamplePaperNav();
